BEGIN; CREATE TABLE public.blank_materials ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL CHECK (char_length(code) BETWEEN 1 AND 80 AND code = btrim(regexp_replace(code, '[[:space:]]+', ' ', 'g'))), specification text NOT NULL CHECK (char_length(btrim(specification)) BETWEEN 1 AND 250), length_mm numeric NOT NULL CHECK (length_mm > 0 AND length_mm <= 100000 AND scale(length_mm) <= 3), width_mm numeric NOT NULL CHECK (width_mm > 0 AND width_mm <= 100000 AND scale(width_mm) <= 3), is_active boolean NOT NULL DEFAULT true ); CREATE UNIQUE INDEX blank_materials_code_unique ON public.blank_materials (upper(code)); ALTER TABLE public.blank_materials ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.blank_materials FROM PUBLIC, anon, authenticated, service_role; GRANT SELECT ON public.blank_materials TO authenticated; GRANT INSERT (code, specification, length_mm, width_mm) ON public.blank_materials TO authenticated; GRANT UPDATE (specification, length_mm, width_mm, is_active) ON public.blank_materials TO authenticated; CREATE POLICY blank_materials_read ON public.blank_materials FOR SELECT TO authenticated USING ((SELECT public.is_approved_active_user())); CREATE POLICY blank_materials_add ON public.blank_materials FOR INSERT TO authenticated WITH CHECK ((SELECT public.is_approved_active_user() AND public.is_admin())); CREATE POLICY blank_materials_edit ON public.blank_materials FOR UPDATE TO authenticated USING ((SELECT public.is_approved_active_user() AND public.is_admin())) WITH CHECK ((SELECT public.is_approved_active_user() AND public.is_admin())); INSERT INTO public.blank_materials (code, specification, length_mm, width_mm) VALUES ('NM-DOWOO-5','Tấm 5L 2 nâu sóng BC',2130,765), ('ITP BAR 01','Tấm 5L nâu mộc sóng AB',500,472), ('180-XN420350-0400','Tấm 5L 2 nâu sóng BC',1606,775), ('180-XN580480-0240','Tấm 5L 2 nâu sóng BC',2186,745), ('#9-2','Tấm 5L 2 nâu sóng BC',1830,615), ('#11','Tấm 5L 2 nâu sóng BC',1494,657), ('IT 002','Tấm 3L 2 nâu sóng A ĐL sóng 150',1840,705), ('93195D NHO 02','Tấm 3L 2 nâu sóng E',1110,1010), ('93195D TO 02','Tấm 3L 2 nâu sóng E',1100,980), ('VB 03','Tấm 3L nâu mộc sóng B',2450,1230), ('93195D 03','Tấm 5L 2 nâu sóng BC',1400,551), ('ITM 003','Tấm 5L 2 nâu sóng BC',1804,713), ('IT 0014 CKD','Tấm 5L 2 nâu sóng BC ĐL sóng 130',1732,689), ('AAC 174','Tấm 3L 2 nâu sóng B',528,518); NOTIFY pgrst, 'reload schema'; COMMIT;
